-- Adds a full dining catalog (spreadsheet export) and, since it needed
-- resort-level filtering rather than a generic 'Resort' bucket, expands the
-- park value set with individual resort codes plus Disney Springs ('DS').
-- 12 rows already existed in the catalog and keep their ids, including 4
-- that previously used the generic 'Resort' park value and now get a real
-- code (Chef Mickey's -> CR, 'Ohana -> POLY, Geyser Point -> WL, BOATHOUSE
-- Snacks -> DS) and one whose park was simply wrong (Topolino's Terrace was
-- tagged HS; it's actually at Riviera Resort -> RIV).
alter table catalog_items add column if not exists dining_tier text;
alter table catalog_items add column if not exists cuisine text;
alter table catalog_items add column if not exists dining_plan_credits text;

update catalog_items set park = 'DS' where id = 's-boathouse';

on conflict (id) do update set
  name = excluded.name, park = excluded.park, category = excluded.category,
  description = excluded.description, price_label = excluded.price_label, price_mid = excluded.price_mid,
  dining_tier = excluded.dining_tier, cuisine = excluded.cuisine, dining_plan_credits = excluded.dining_plan_credits;
