insert into catalog_items (id, name, park, category, description, price_label, price_mid, dining_tier, cuisine, dining_plan_credits) values
  ('d-crt', 'Cinderella''s Royal Table', 'MK', 'restaurant', 'Breakfast, lunch, and dinner inside Cinderella Castle with princess characters. The most iconic dining reservation in all of Walt Disney World — book the moment your 60-day window opens.', '$65–$90/pp', 77, 'character_dining', 'American, Disney Princesses', '2'),
  ('d-bog', 'Be Our Guest Restaurant', 'MK', 'restaurant', 'Three ornate dining rooms inside Beast''s enchanted castle. Breakfast and lunch are quick service counter order; dinner is table service with a prix-fixe French-inspired menu. Among the most atmospheric dining experiences in the parks.', '$55–$75/pp', 65, 'table_service', 'French-inspired', '2 (dinner) / QS (B&L)'),
  ('d-the-crystal-palace', 'The Crystal Palace', 'MK', 'restaurant', 'Victorian-style buffet with Winnie the Pooh, Tigger, Piglet, and Eeyore. A warm family option at the end of Main Street with a wide menu for picky eaters. Breakfast, lunch, and dinner available.', '$45–$65/pp', 55, 'character_dining', 'American buffet', '1'),
  ('d-liberty-tree-tavern', 'Liberty Tree Tavern', 'MK', 'restaurant', 'Colonial American-themed restaurant serving a family-style Thanksgiving feast — turkey, pot roast, and sides — at dinner. Lunch is à la carte. One of the better food values for a sit-down in the park.', '$45–$60/pp', 52, 'table_service', 'American family-style', '1'),
  ('d-skipper', 'Jungle Navigation Co. Ltd. Skipper Canteen', 'MK', 'restaurant', 'Quirky, pun-filled restaurant themed around the Jungle Cruise explorers. Serves globally inspired dishes in three themed rooms. Often easier to book last-minute than other MK table service spots.', '$35–$55/pp', 45, 'table_service', 'Global, themed', '1'),
  ('d-tony-s-town-square-restaurant', 'Tony''s Town Square Restaurant', 'MK', 'restaurant', 'Lady and the Tramp-themed Italian-American restaurant at the Main Street entrance. Pasta, chicken, and fish options — one of the more accessible table service reservations in Magic Kingdom.', '$35–$55/pp', 45, 'table_service', 'Italian-American', '1'),
  ('d-the-plaza-restaurant', 'The Plaza Restaurant', 'MK', 'restaurant', 'Bright Victorian-style diner at the end of Main Street serving burgers, sandwiches, and milkshakes. One of the more affordable table service options in Magic Kingdom.', '$25–$40/pp', 32, 'table_service', 'American sandwiches & burgers', '1'),
  ('d-the-diamond-horseshoe', 'The Diamond Horseshoe', 'MK', 'restaurant', 'Western-themed restaurant in Frontierland with a prix-fixe family-style menu. A lower-profile reservation that''s easier to snag while still offering a solid sit-down meal.', '$40–$55/pp', 47, 'table_service', 'American family-style', '1'),
  ('s-cosmic-ray-s-starlight-cafe', 'Cosmic Ray''s Starlight Cafe', 'MK', 'snack', 'Largest quick service in Magic Kingdom, with multiple bays serving burgers, rotisserie chicken, and salads. An animatronic lounge singer entertains during peak hours.', '$12–$18/pp', 15, 'quick_service', 'American', 'QS'),
  ('s-pecos-bill-tall-tale-inn-and', 'Pecos Bill Tall Tale Inn and Cafe', 'MK', 'snack', 'Tex-Mex staples — burgers, nachos, and fajita bowls — in a Frontierland Western setting. Toppings bar makes it one of the more customizable quick service spots in the park.', '$12–$17/pp', 14, 'quick_service', 'Tex-Mex', 'QS'),
  ('s-columbia-harbour-house', 'Columbia Harbour House', 'MK', 'snack', 'Beloved quick service in Liberty Square with clam chowder, lobster rolls, and fried fish. The upstairs seating area is a hidden gem for escaping crowds.', '$12–$18/pp', 15, 'quick_service', 'American seafood & sandwiches', 'QS'),
  ('s-pinocchio-village-haus', 'Pinocchio Village Haus', 'MK', 'snack', 'Flatbreads, pasta, and salads with a window view into the it''s a small world boat ride. Fun location — window seats are popular with young kids.', '$12–$17/pp', 14, 'quick_service', 'Italian-American', 'QS'),
  ('s-casey-s-corner', 'Casey''s Corner', 'MK', 'snack', 'The park''s beloved hot dog stand on Main Street with corn dog nuggets, hot dogs with creative toppings, and live piano entertainment.', '$10–$16/pp', 13, 'quick_service', 'American hot dogs', 'QS'),
  ('s-gaston-s-tavern', 'Gaston''s Tavern', 'MK', 'snack', 'Beauty and the Beast-themed snack spot in Fantasyland. Famous for LeFou''s Brew and oversized cinnamon rolls.', '$8–$15/pp', 11, 'quick_service', 'Snacks & drinks', 'QS'),
  ('s-main-street-bakery', 'Main Street Bakery', 'MK', 'snack', 'A Starbucks inside a charming Victorian bakery setting. Full Starbucks menu plus Disney-themed treats. One of the park''s most popular morning stops.', '$6–$14/pp', 10, 'quick_service', 'Starbucks & baked goods', 'QS'),
  ('s-the-lunching-pad', 'The Lunching Pad', 'MK', 'snack', 'An outdoor snack window under the Tomorrowland rocket with frozen drinks, pretzels, and hot dogs. A convenient grab-and-go spot between Tomorrowland rides.', '$6–$12/pp', 9, 'snack_kiosk', 'Snacks & drinks', 'QS/Snack'),
  ('s-sleepy-hollow', 'Sleepy Hollow', 'MK', 'snack', 'A Liberty Square snack spot best known for its fresh funnel cake and waffle sandwiches. A popular sweet treat stop.', '$8–$14/pp', 11, 'snack_kiosk', 'Waffles & snacks', 'QS/Snack'),
  ('s-golden-oak-outpost', 'Golden Oak Outpost', 'MK', 'snack', 'Small Frontierland kiosk serving chicken strips and waffle fries. A convenient, no-frills snack option near Big Thunder Mountain.', '$8–$13/pp', 10, 'snack_kiosk', 'Chicken & waffle fries', 'QS/Snack'),
  ('s-tortuga-tavern', 'Tortuga Tavern', 'MK', 'snack', 'A seasonal quick service spot in Adventureland serving tacos and nachos. Open selectively — check the My Disney Experience app before counting on it.', '$10–$15/pp', 12, 'snack_kiosk', 'Mexican snacks (seasonal)', 'QS/Snack'),
  ('d-le-cellier-steakhouse', 'Le Cellier Steakhouse', 'EPCOT', 'restaurant', 'Arguably the best beef at Walt Disney World, inside the Canada pavilion. Famous for the Canadian Cheddar Cheese Soup and a deep wine list. Book at the 60-day window — one of EPCOT''s most sought reservations.', '$85–$120/pp', 102, 'signature', 'Canadian steakhouse', '2'),
  ('d-akershus-royal-banquet-hall', 'Akershus Royal Banquet Hall', 'EPCOT', 'restaurant', 'Princess character dining in a Norwegian castle with a Scandinavian buffet. A more reliably bookable alternative to Cinderella''s Royal Table for princess-seekers.', '$45–$65/pp', 55, 'character_dining', 'Norwegian buffet, Disney Princesses', '2 (L&D) / 1 (B)'),
  ('d-garden-grill', 'Garden Grill', 'EPCOT', 'restaurant', 'A slowly rotating restaurant above Living with the Land with Chip, Dale, Mickey, and Pluto. Family-style American meals with ingredients sourced from the greenhouse below.', '$50–$65/pp', 57, 'character_dining', 'American family-style', '1'),
  ('d-space220', 'Space 220', 'EPCOT', 'restaurant', 'A theatrical experience simulating dining 220 miles above Earth. Guests ride a ''space elevator'' to a restaurant with panoramic views of Earth from orbit. Not on the dining plan. Atmosphere is the main event.', '$55–$85/pp', 70, 'table_service', 'American, space-themed', 'N/A'),
  ('d-coral-reef-restaurant', 'Coral Reef Restaurant', 'EPCOT', 'restaurant', 'Dine alongside The Seas pavilion''s massive aquarium while sharks, rays, and sea turtles swim by. Seafood-forward menu with some land options.', '$45–$70/pp', 57, 'table_service', 'Seafood', '1'),
  ('d-chefs-de-france', 'Chefs de France', 'EPCOT', 'restaurant', 'Casual French bistro in the France pavilion serving crepes, soups, steak frites, and classic French desserts. Consistently reliable and moderately priced.', '$40–$65/pp', 52, 'table_service', 'French bistro', '1'),
  ('d-biergarten-restaurant', 'Biergarten Restaurant', 'EPCOT', 'restaurant', 'Festive German buffet in an indoor Oktoberfest setting with live oompah band. Sausages, schnitzel, pretzels, and German beers.', '$45–$60/pp', 52, 'table_service', 'German buffet', '1'),
  ('d-monsieur-paul', 'Monsieur Paul', 'EPCOT', 'restaurant', 'An upscale French fine dining experience above Chefs de France in the France pavilion. Multi-course prix-fixe menu with classic French technique and seasonal ingredients. One of EPCOT''s best-kept dining secrets.', '$95–$140/pp', 117, 'signature', 'French fine dining', '2'),
  ('d-rose-and-crown-dining-room', 'Rose & Crown Dining Room', 'EPCOT', 'restaurant', 'Traditional British pub and restaurant in the UK pavilion. Fish and chips, shepherd''s pie, and British ales. Patio seating has one of the best fireworks views in EPCOT.', '$40–$65/pp', 52, 'table_service', 'British pub fare', '1'),
  ('d-teppan-edo', 'Teppan Edo', 'EPCOT', 'restaurant', 'Hibachi-style teppanyaki in the Japan pavilion where chefs cook at the table with skill and flair. Fresh steak, chicken, seafood, and vegetables. Great for larger groups.', '$50–$75/pp', 62, 'table_service', 'Japanese teppanyaki', '1'),
  ('d-via-napoli-ristorante-e', 'Via Napoli Ristorante e Pizzeria', 'EPCOT', 'restaurant', 'Authentic wood-fired Neapolitan pizza in the Italy pavilion, cooked in massive ovens named after Italian volcanoes. One of the best meals in all of EPCOT.', '$35–$55/pp', 45, 'table_service', 'Neapolitan pizza', '1'),
  ('d-tutto-italia-ristorante', 'Tutto Italia Ristorante', 'EPCOT', 'restaurant', 'Traditional Italian restaurant in the Italy pavilion with pastas, risotto, and antipasti. Often easier to book than Via Napoli next door.', '$40–$65/pp', 52, 'table_service', 'Italian', '1'),
  ('d-tutto-gusto-wine-cellar', 'Tutto Gusto Wine Cellar', 'EPCOT', 'restaurant', 'An intimate wine cellar lounge below Tutto Italia. No reservations needed — walk in for Italian wines, charcuterie, and small plates. A peaceful World Showcase refuge.', '$10–$25/pp', 17, 'lounge_bar', 'Italian wine & small plates', 'N/A'),
  ('d-san-angel-inn-restaurante', 'San Angel Inn Restaurante', 'EPCOT', 'restaurant', 'A dramatic indoor restaurant inside the Mexico pavilion set beneath a simulated night sky near the Gran Fiesta Tour ride. Atmospheric and unique.', '$40–$60/pp', 50, 'table_service', 'Mexican', '1'),
  ('d-la-hacienda-de-san-angel', 'La Hacienda de San Angel', 'EPCOT', 'restaurant', 'Lakeside Mexican restaurant in the Mexico pavilion with waterfront views. Contemporary Mexican cuisine — tacos, enchiladas, and seafood with a solid margarita program.', '$45–$65/pp', 55, 'table_service', 'Mexican lakeside', '1'),
  ('d-nine-dragons-restaurant', 'Nine Dragons Restaurant', 'EPCOT', 'restaurant', 'Chinese cuisine in the China pavilion with dim sum, Peking duck, and wok-fired dishes. Often overlooked, which can mean better walk-up availability.', '$35–$55/pp', 45, 'table_service', 'Chinese', '1'),
  ('d-shiki-sai-sushi-izakaya', 'Shiki-Sai: Sushi Izakaya', 'EPCOT', 'restaurant', 'A stylish izakaya-style concept in the Japan pavilion serving sushi, ramen, and small plates. A notable upgrade over the previous Tatsumi restaurant.', '$45–$70/pp', 57, 'table_service', 'Japanese sushi & izakaya', '1'),
  ('d-le-creperie-de-paris', 'Le Creperie de Paris', 'EPCOT', 'restaurant', 'Sweet and savory crepes in the France pavilion near the Remy ride. Galettes and dessert crepes are both excellent — one of the newer and most delightful EPCOT dining additions.', '$25–$40/pp', 32, 'table_service', 'French crepes', '1'),
  ('d-spice-road-table', 'Spice Road Table', 'EPCOT', 'restaurant', 'A casual waterfront restaurant in the Morocco pavilion serving Mediterranean small plates and flatbreads. Patio seating offers excellent EPCOT lagoon views — great for festival evenings.', '$30–$50/pp', 40, 'table_service', 'Mediterranean small plates', '1'),
  ('s-sunshine-seasons', 'Sunshine Seasons', 'EPCOT', 'snack', 'One of the best quick service locations at any Disney park, inside The Land pavilion. Rotating menu with rotisserie chicken, Asian noodle bowls, sandwiches, and fresh salads.', '$13–$19/pp', 16, 'quick_service', 'American & global rotating', 'QS'),
  ('s-les-halles-boulangerie-p', 'Les Halles Boulangerie-Pâtisserie', 'EPCOT', 'snack', 'Authentic French bakery in the France pavilion with croissants, baguette sandwiches, quiche, and pastries. The chocolate croissant alone is worth the stop.', '$8–$18/pp', 13, 'quick_service', 'French bakery', 'QS'),
  ('s-katsura-grill', 'Katsura Grill', 'EPCOT', 'snack', 'Garden-setting counter service in the Japan pavilion with sushi, udon noodles, and teriyaki. Peaceful outdoor seating makes it one of the more relaxing quick service spots.', '$12–$18/pp', 15, 'quick_service', 'Japanese', 'QS'),
  ('s-la-cantina-de-san-angel', 'La Cantina de San Angel', 'EPCOT', 'snack', 'Outdoor waterfront quick service in the Mexico pavilion with tacos, nachos, and churros. The lakeside seating offers some of the best views in World Showcase.', '$12–$17/pp', 14, 'quick_service', 'Mexican', 'QS'),
  ('s-regal-eagle-smokehouse', 'Regal Eagle Smokehouse', 'EPCOT', 'snack', 'Patriotic BBQ counter service in the American Adventure pavilion with pulled pork, brisket, smoked chicken, and generous sides. One of EPCOT''s most satisfying quick service options.', '$13–$19/pp', 16, 'quick_service', 'American BBQ', 'QS'),
  ('s-connections-cafe-and-eatery', 'Connections Cafe & Eatery', 'EPCOT', 'snack', 'Large modern quick service in World Celebration with rotating options and a Starbucks component. A convenient central hub for fast meals.', '$12–$18/pp', 15, 'quick_service', 'American & global', 'QS'),
  ('s-sommerfest', 'Sommerfest', 'EPCOT', 'snack', 'Small outdoor kiosk near Biergarten in the Germany pavilion. Bratwurst, soft pretzels, and German beers. A great snack stop while exploring World Showcase.', '$8–$14/pp', 11, 'snack_kiosk', 'German snacks', 'QS/Snack'),
  ('s-refreshment-outpost', 'Refreshment Outpost', 'EPCOT', 'snack', 'An outdoor snack kiosk between Germany and China pavilions. Frozen beverages, chips, and light snacks. A convenient mid-Showcase refueling stop.', '$6–$12/pp', 9, 'snack_kiosk', 'Snacks & drinks', 'QS/Snack'),
  ('s-yorkshire-county-fish-shop', 'Yorkshire County Fish Shop', 'EPCOT', 'snack', 'A small window in the UK pavilion serving classic British fish and chips in a paper cone. Simple, consistently good, and a World Showcase favorite.', '$10–$15/pp', 12, 'snack_kiosk', 'British fish & chips', 'QS/Snack'),
  ('s-cr-pes-emporter', 'Crêpes À Emporter', 'EPCOT', 'snack', 'A small crepe window in the France pavilion for quick sweet or savory crepes to enjoy while strolling. The walk-up companion to Le Creperie de Paris next door.', '$8–$12/pp', 10, 'snack_kiosk', 'French crepes to-go', 'QS/Snack'),
  ('s-lotus-blossom-cafe', 'Lotus Blossom Cafe', 'EPCOT', 'snack', 'Counter service in the China pavilion with egg rolls, pot stickers, and stir-fry dishes. A reliable and affordable option in World Showcase.', '$11–$16/pp', 13, 'quick_service', 'Chinese', 'QS'),
  ('s-kringla-bakeri-og-kafe', 'Kringla Bakeri Og Kafe', 'EPCOT', 'snack', 'A Norwegian bakery in the Norway pavilion with school bread, lefse, and open-faced sandwiches. The school bread (custard-filled pastry with coconut topping) is a beloved EPCOT snack.', '$8–$14/pp', 11, 'quick_service', 'Norwegian bakery', 'QS'),
  ('s-fife-and-drum-tavern', 'Fife and Drum Tavern', 'EPCOT', 'snack', 'An outdoor snack cart near the American Adventure pavilion serving turkey legs, popcorn, and frozen slushies. The turkey leg is one of Walt Disney World''s most iconic snacks.', '$8–$14/pp', 11, 'snack_kiosk', 'American snacks', 'QS/Snack'),
  ('d-brownderby', 'The Hollywood Brown Derby', 'HS', 'restaurant', 'Recreation of the iconic 1930s Hollywood supper club. Upscale American cuisine, the original Cobb Salad, and excellent service. One of the better Signature experiences in the parks — elegant but approachable.', '$75–$110/pp', 92, 'signature', 'American fine dining', '2'),
  ('d-hollywood-and-vine', 'Hollywood & Vine', 'HS', 'restaurant', 'Character buffet rotating by season — Junior Chef characters at breakfast/lunch, seasonal characters at dinner. Consistently popular for families.', '$45–$65/pp', 55, 'character_dining', 'American buffet, seasonal characters', '1'),
  ('d-50-s-prime-time-caf', '50''s Prime Time Café', 'HS', 'restaurant', 'A 1950s kitchen-themed diner where servers scold you for not eating your vegetables. Meatloaf, pot roast, chicken pot pie, and milkshakes. One of Disney''s most entertaining dining experiences.', '$35–$55/pp', 45, 'table_service', 'American comfort food', '1'),
  ('d-scifi', 'Sci-Fi Dine-In Theater Restaurant', 'HS', 'restaurant', 'Dine in vintage cars inside a simulated drive-in movie theater with sci-fi B-movie trailers on loop. The atmosphere is the star — burgers and shakes are reliable.', '$30–$50/pp', 40, 'table_service', 'American burgers & sandwiches', '1'),
  ('d-roundup-rodeo-bbq', 'Roundup Rodeo BBQ', 'HS', 'restaurant', 'Toy Story-themed all-you-care-to-enjoy BBQ in Toy Story Land with smoked meats, sides, and themed desserts. Strong value for hearty eaters.', '$45–$60/pp', 52, 'table_service', 'BBQ family-style, Toy Story themed', '1'),
  ('d-the-hollywood-brown-derby', 'The Hollywood Brown Derby Lounge', 'HS', 'restaurant', 'Walk-up lounge adjacent to the Brown Derby serving the full restaurant menu without a reservation. One of Hollywood Studios'' best-kept secrets for table service food without the ADR.', '$12–$25/pp', 18, 'lounge_bar', 'American small plates', 'N/A'),
  ('s-docking-bay-7-food-and-cargo', 'Docking Bay 7 Food and Cargo', 'HS', 'snack', 'The main counter service in Galaxy''s Edge with creative Star Wars-themed dishes — smoked Kaadu ribs, plant-based Nuna turkey jerky, and inspired drinks. One of Disney''s most creative QS menus.', '$13–$19/pp', 16, 'quick_service', 'Galactic/American', 'QS'),
  ('s-ronto-roasters', 'Ronto Roasters', 'HS', 'snack', 'Small Galaxy''s Edge kiosk where a spit-roasting droid cooks meats for wraps. The Ronto Wrap is one of the most beloved quick service items in any Disney park.', '$11–$15/pp', 13, 'quick_service', 'Star Wars-themed wraps', 'QS'),
  ('s-woody-s-lunch-box', 'Woody''s Lunch Box', 'HS', 'snack', 'Toy Story Land counter service with totchos, grilled cheese, and lemon-lime punch. Simple, crowd-pleasing menu with Toy Story charm.', '$11–$16/pp', 13, 'quick_service', 'American comfort food', 'QS'),
  ('s-backlot-express', 'Backlot Express', 'HS', 'snack', 'Straightforward burger and chicken sandwich spot near Star Tours. Reliable and often less crowded than other locations.', '$12–$17/pp', 14, 'quick_service', 'American burgers', 'QS'),
  ('s-abc-commissary', 'ABC Commissary', 'HS', 'snack', 'Large, air-conditioned counter service with a rotating menu including burgers, fish and chips, and bowls. Good for large groups needing quick, efficient service.', '$12–$18/pp', 15, 'quick_service', 'American & international', 'QS'),
  ('s-fairfax-fare', 'Fairfax Fare', 'HS', 'snack', 'An outdoor counter service on Sunset Boulevard near Tower of Terror with pulled pork, corn dogs, and loaded fries.', '$11–$16/pp', 13, 'quick_service', 'American BBQ & comfort', 'QS'),
  ('s-rosie-s-all-american-cafe', 'Rosie''s All-American Cafe', 'HS', 'snack', 'Outdoor counter service near the Theater of the Stars with burgers, chicken sandwiches, and plant-based options.', '$11–$16/pp', 13, 'quick_service', 'American', 'QS'),
  ('s-catalina-eddie-s', 'Catalina Eddie''s', 'HS', 'snack', 'Pizza and pasta counter service on Sunset Boulevard. A reliable fallback option — particularly convenient given its location near Tower of Terror and Rock ''n'' Roller Coaster.', '$11–$16/pp', 13, 'quick_service', 'Pizza & pasta', 'QS'),
  ('s-trolley-car-caf', 'Trolley Car Café', 'HS', 'snack', 'A Starbucks on Hollywood Boulevard. Full menu of Starbucks drinks and pastries. The best coffee option in the park.', '$5–$14/pp', 9, 'quick_service', 'Starbucks', 'QS'),
  ('s-dockside-diner', 'Dockside Diner', 'HS', 'snack', 'Outdoor waterfront counter service with hot dogs, nachos, and loaded fries. A convenient stop near the park entrance.', '$10–$15/pp', 12, 'quick_service', 'American', 'QS'),
  ('d-tiffins-restaurant', 'Tiffins Restaurant', 'AK', 'restaurant', 'Animal Kingdom''s flagship fine dining, themed around global exploration with hand-painted murals from Disney''s research travels. Globally inspired menu with the most interesting dishes in the park.', '$75–$110/pp', 92, 'signature', 'Global fine dining', '2'),
  ('d-tusker-house-restaurant', 'Tusker House Restaurant', 'AK', 'restaurant', 'Safari-themed buffet with Donald, Daisy, Mickey, and Goofy in safari attire. African-inspired dishes alongside familiar American fare. One of the better character dining values on property.', '$45–$65/pp', 55, 'character_dining', 'African-inspired buffet, Donald & friends', '1'),
  ('d-yak-and-yeti-restaurant', 'Yak & Yeti Restaurant', 'AK', 'restaurant', 'Asian fusion in the Asia section with fried rice, noodle bowls, and Peking duck. Solid mid-range option with atmospheric decor.', '$35–$55/pp', 45, 'table_service', 'Asian fusion', '1'),
  ('d-rainforest-cafe', 'Rainforest Cafe', 'AK', 'restaurant', 'Jungle-themed chain at the Animal Kingdom entrance with animatronic animals and thunderstorms. Broad American menu — reliable for younger kids, though food is inconsistent.', '$30–$50/pp', 40, 'table_service', 'American', '1'),
  ('d-nomad-lounge', 'Nomad Lounge', 'AK', 'restaurant', 'The walk-up lounge adjacent to Tiffins serving the full Tiffins appetizer menu and creative cocktails. Widely regarded as one of the best lounges at Walt Disney World — worth a dedicated stop.', '$12–$28/pp', 20, 'lounge_bar', 'Global small plates', 'N/A'),
  ('s-satu-li-canteen', 'Satu''li Canteen', 'AK', 'snack', 'Widely considered one of the best quick service locations at any Disney park. Customizable bowls in Pandora with creative bases and proteins. Creative, healthy, and genuinely delicious.', '$13–$19/pp', 16, 'quick_service', 'Pandora/global bowls', 'QS'),
  ('s-flame-tree-barbecue', 'Flame Tree Barbecue', 'AK', 'snack', 'Open-air BBQ on Discovery Island with smoked ribs, pulled pork, and chicken. The outdoor waterfront seating is some of the most scenic at any Disney park.', '$13–$19/pp', 16, 'quick_service', 'American BBQ', 'QS'),
  ('s-harambe-market', 'Harambe Market', 'AK', 'snack', 'Outdoor market in the Africa section with multiple food windows serving African-inspired street food — grilled chicken skewers, ribs, corn, and plantains.', '$12–$18/pp', 15, 'quick_service', 'African-inspired street food', 'QS'),
  ('s-pizzafari', 'Pizzafari', 'AK', 'snack', 'Colorful pizza and pasta counter service on Discovery Island. Basic but kid-friendly — reliable when picky eaters need something familiar.', '$11–$16/pp', 13, 'quick_service', 'Pizza & pasta', 'QS'),
  ('s-creature-comforts', 'Creature Comforts', 'AK', 'snack', 'A Starbucks at Disney''s Animal Kingdom near the park entrance. Full Starbucks menu in a theme-appropriate building. Best morning coffee option in the park.', '$5–$14/pp', 9, 'quick_service', 'Starbucks', 'QS'),
  ('s-yak-and-yeti-local-food-cafes', 'Yak & Yeti Local Food Cafes', 'AK', 'snack', 'Outdoor counter service adjacent to the Yak & Yeti Restaurant serving Asian-inspired bowls, chicken teriyaki, and fried rice. A budget-friendly alternative to the table service restaurant next door.', '$11–$16/pp', 13, 'quick_service', 'Asian-American', 'QS'),
  ('s-mr-kamal-s', 'Mr. Kamal''s', 'AK', 'snack', 'A small kiosk in Asia serving seasoned fries, hummus, and Middle Eastern-inspired snacks. A tasty and underrated snack stop.', '$8–$14/pp', 11, 'snack_kiosk', 'Middle Eastern snacks', 'QS/Snack'),
  ('d-chef-art-smith-s-homecomin', 'Chef Art Smith''s Homecomin''', 'DS', 'restaurant', 'Celebrity chef Art Smith''s ode to Florida Southern cooking. Famous for Aunt Liz''s fried chicken (brined 24 hours), hush puppies, deviled eggs, and the legendary Moonshine Mama cake. One of Disney Springs'' best.', '$35–$60/pp', 47, 'table_service', 'Southern American', '1'),
  ('d-jaleo-by-jos-andr-s', 'Jaleo by José Andrés', 'DS', 'restaurant', 'José Andrés'' acclaimed Spanish tapas restaurant. Exceptional paella, jamón Ibérico, and creative small plates. One of the most sophisticated dining options at Walt Disney World.', '$50–$90/pp', 70, 'table_service', 'Spanish tapas', '2'),
  ('d-morimoto-asia', 'Morimoto Asia', 'DS', 'restaurant', 'Iron Chef Morimoto''s pan-Asian restaurant with sushi, Peking duck, and dim sum. Lunch requires 1 dining plan credit; dinner requires 2.', '$45–$80/pp', 62, 'table_service', 'Pan-Asian', '2 (D) / 1 (L)'),
  ('d-the-boathouse', 'The Boathouse', 'DS', 'restaurant', 'Upscale waterfront restaurant specializing in fresh seafood and premium steaks, with antique amphicar water tours. One of Disney Springs'' highest-rated for food quality.', '$50–$90/pp', 70, 'table_service', 'Seafood & steakhouse', '2'),
  ('d-paddlefish', 'Paddlefish', 'DS', 'restaurant', 'A large seafood restaurant inside a repurposed steamboat on the water. Fresh seafood platters, lobster, and steaks in a festive, lively setting.', '$45–$75/pp', 60, 'table_service', 'Seafood', '2'),
  ('d-raglan-road-irish-pub', 'Raglan Road Irish Pub', 'DS', 'restaurant', 'Authentic Irish pub imported from Ireland with live music, step dancing, and solid Irish food — shepherd''s pie, fish and chips, and hearty stews. Great atmosphere.', '$30–$55/pp', 42, 'table_service', 'Irish pub', '1'),
  ('d-the-edison', 'The Edison', 'DS', 'restaurant', 'Industrial-chic restaurant with live entertainment, fire performers, and an impressive bar program. Comfort food elevated with creative twists — great for adults.', '$35–$60/pp', 47, 'table_service', 'American, industrial theme', '1'),
  ('d-frontera-cocina', 'Frontera Cocina', 'DS', 'restaurant', 'Celebrity chef Rick Bayless''s Mexican restaurant with regional Mexican cuisine — enchiladas, ceviche, tacos, and house-made guacamole.', '$30–$50/pp', 40, 'table_service', 'Mexican', '1'),
  ('d-maria-and-enzo-s-ristorante', 'Maria & Enzo''s Ristorante', 'DS', 'restaurant', 'Elegant Italian-American restaurant in a repurposed 1930s airplane terminal. Quality pasta, seafood, and a good wine list.', '$35–$60/pp', 47, 'table_service', 'Italian', '1'),
  ('d-enzo-s-hideaway', 'Enzo''s Hideaway', 'DS', 'restaurant', 'A hidden tunnel bar and restaurant beneath Maria & Enzo''s serving Roman-style pasta and Italian cocktails. The underground setting and speakeasy vibe make it one of Disney Springs'' most atmospheric dining rooms.', '$30–$50/pp', 40, 'table_service', 'Italian', '1'),
  ('d-splitsville-dining-room', 'Splitsville Dining Room', 'DS', 'restaurant', 'Retro bowling alley and restaurant with sushi, flatbreads, burgers, and milkshakes. Best for groups who want to bowl while eating.', '$25–$45/pp', 35, 'table_service', 'American bowling alley', '1'),
  ('d-t-rex', 'T-REX', 'DS', 'restaurant', 'Dinosaur-themed chain restaurant with animatronic dinosaurs and a broad American menu. Loud and entertaining — particularly popular with younger kids.', '$25–$45/pp', 35, 'table_service', 'American', '1'),
  ('d-house-of-blues-restaurant-and', 'House of Blues Restaurant & Bar', 'DS', 'restaurant', 'Live music venue and restaurant with Southern-inspired American food — jambalaya, catfish, and ribs. Gospel Brunch on Sundays is a fan favorite.', '$25–$45/pp', 35, 'table_service', 'American Southern', '1'),
  ('d-planet-hollywood', 'Planet Hollywood', 'DS', 'restaurant', 'The remodeled Planet Hollywood Observatory with American comfort food — burgers, pasta, and loaded appetizers. A solid mid-range option at Disney Springs.', '$25–$45/pp', 35, 'table_service', 'American', '1'),
  ('d-wine-bar-george', 'Wine Bar George', 'DS', 'restaurant', 'A sophisticated wine bar by Master Sommelier George Miliotes with an impressive by-the-glass program and charcuterie boards. One of Disney Springs'' best spots for adults. Not on the dining plan.', '$15–$35/pp', 25, 'lounge_bar', 'Wine & small plates', 'N/A'),
  ('d-jock-lindsey-s-hangar-bar', 'Jock Lindsey''s Hangar Bar', 'DS', 'restaurant', 'Indiana Jones-themed bar themed around Indy''s pilot friend. Creative aviation-themed cocktails and shareable snacks. A beloved Disney Springs bar for Disney fans.', '$12–$25/pp', 18, 'lounge_bar', 'American snacks & cocktails', 'N/A'),
  ('s-d-luxe-burger', 'D-Luxe Burger', 'DS', 'snack', 'One of the best quick service burgers at Walt Disney World — creative smash-style burgers with quality toppings in a modern setting.', '$14–$20/pp', 17, 'quick_service', 'Gourmet burgers', 'QS'),
  ('s-the-polite-pig', 'The Polite Pig', 'DS', 'snack', 'Well-regarded BBQ counter service with smoked meats, creative sides, and a craft cocktail bar. Consistent quality at reasonable prices.', '$13–$20/pp', 16, 'quick_service', 'BBQ', 'QS'),
  ('s-chicken-guy', 'Chicken Guy!', 'DS', 'snack', 'Guy Fieri''s chicken tender concept with a wide variety of dipping sauces. Simple concept done well — a reliable, affordable Disney Springs option.', '$10–$16/pp', 13, 'quick_service', 'Chicken tenders', 'QS'),
  ('s-cookes-of-dublin', 'Cookes of Dublin', 'DS', 'snack', 'An Irish counter service adjacent to Raglan Road serving fish and chips, battered sausages, and Irish staples. Great value and a more casual companion to the pub next door.', '$11–$16/pp', 13, 'quick_service', 'Irish fish & chips', 'QS'),
  ('s-amorette-s-patisserie', 'Amorette''s Patisserie', 'DS', 'snack', 'An elegant patisserie selling decorated mini cakes, macarons, and pastries. Famous for the Mickey-shaped dome cake. A go-to for Disney Springs desserts.', '$6–$15/pp', 10, 'snack_kiosk', 'French pastries', 'QS/Snack'),
  ('s-everglazed-donuts', 'Everglazed Donuts', 'DS', 'snack', 'A creative donut shop at Disney Springs with unique flavors, warm donuts, and craft coffee. One of the newer and more delightful sweet stops on the Springs.', '$5–$12/pp', 8, 'snack_kiosk', 'Donuts', 'QS/Snack'),
  ('d-victoria-and-albert-s', 'Victoria & Albert''s', 'GF', 'restaurant', 'Walt Disney World''s crown jewel of fine dining — a multi-course prix-fixe tasting menu at the Grand Floridian. The only AAA Five Diamond restaurant operated by a U.S. theme park. Formal dress code, guests must be 10+. Wine pairings start at $210. Book at the 60-day window.', '$375–$375/pp', 375, 'signature', 'Modern American tasting menu', 'N/A'),
  ('d-narcoossee-s', 'Narcoossee''s', 'GF', 'restaurant', 'Upscale waterfront restaurant on the Seven Seas Lagoon with Magic Kingdom fireworks views. Lobster, prime beef, and fresh seafood in a relaxed lakeside setting.', '$85–$130/pp', 107, 'signature', 'Seafood & steakhouse', '2'),
  ('d-citricos', 'Citricos', 'GF', 'restaurant', 'Elegant Mediterranean-inspired restaurant inside the Grand Floridian with refined fish, lamb, and pasta. Often overlooked in favor of Narcoossee''s — a hidden gem for quality cooking.', '$75–$110/pp', 92, 'signature', 'Mediterranean', '2'),
  ('d-grand-floridian-cafe', 'Grand Floridian Cafe', 'GF', 'restaurant', 'Lovely, reliable table service inside the Grand Floridian lobby serving American classics for breakfast, lunch, and dinner. A relaxed and more affordable alternative to the resort''s signature spots.', '$30–$55/pp', 42, 'table_service', 'American', '1'),
  ('d-garden-view-tea-room', 'Garden View Tea Room', 'GF', 'restaurant', 'A traditional British afternoon tea experience inside the Grand Floridian. Finger sandwiches, scones, and sweets served in a beautiful garden-view setting. Returned in early 2026. Reservations required.', '$35–$65/pp', 50, 'table_service', 'British afternoon tea', '1'),
  ('d-1900-park-fare', '1900 Park Fare', 'GF', 'restaurant', 'Victorian-era themed character buffet featuring Cinderella, Prince Charming, Anastasia, Drizella, and the Fairy Godmother. One of the more unique character lineups at any WDW dining experience.', '$45–$65/pp', 55, 'character_dining', 'American buffet, Cinderella & Prince Charming', '1'),
  ('d-enchanted-rose', 'Enchanted Rose', 'GF', 'restaurant', 'Beauty and the Beast-themed lounge inside the Grand Floridian with creative cocktails and elegant small plates. One of Disney World''s most beautifully themed bar spaces.', '$12–$25/pp', 18, 'lounge_bar', 'Cocktails & small plates', 'N/A'),
  ('s-gasparilla-island-grill', 'Gasparilla Island Grill', 'GF', 'snack', 'The Grand Floridian''s quick service option with grab-and-go meals, hot foods, and baked goods. Available 24 hours — a convenient late-night option for resort guests.', '$10–$17/pp', 13, 'quick_service', 'American', 'QS'),
  ('s-beaches-pool-bar-and-grill', 'Beaches Pool Bar & Grill', 'GF', 'snack', 'Pool bar serving burgers, sandwiches, and cocktails at the Grand Floridian''s main pool. Resort guests only.', '$10–$18/pp', 14, 'pool_bar', 'American snacks & drinks', 'QS'),
  ('s-courtyard-pool-bar', 'Courtyard Pool Bar', 'GF', 'snack', 'A smaller pool bar at the Grand Floridian''s courtyard pool serving beverages and light snacks. Resort guests only.', '$8–$15/pp', 11, 'pool_bar', 'Drinks & snacks', 'QS'),
  ('d-california-grill', 'California Grill', 'CR', 'restaurant', 'Celebrated rooftop restaurant with sweeping Magic Kingdom views and nightly fireworks. Excellent sushi, wood-fired flatbreads, and seasonal American cuisine. Guests can return to the observation deck after dinner for fireworks.', '$90–$130/pp', 110, 'signature', 'Contemporary American', '2'),
  ('d-chefmickeys', 'Chef Mickey''s', 'CR', 'restaurant', 'Monorail-view character buffet with Mickey, Minnie, Donald, Goofy, and Pluto. One of the most popular character dining reservations on property — book at the 60-day window.', '$45–$65/pp', 55, 'character_dining', 'American buffet, Fab Five', '1'),
  ('d-steakhouse-71', 'Steakhouse 71', 'CR', 'restaurant', 'Stylish mid-century steakhouse at the Contemporary. Excellent breakfast and lunch value; dinner features premium steaks and sides. One of the better value-to-quality ratios among resort restaurants.', '$35–$70/pp', 52, 'table_service', 'American steakhouse', '1'),
  ('d-steakhouse-71-lounge', 'Steakhouse 71 Lounge', 'CR', 'restaurant', 'The lounge adjacent to Steakhouse 71 where guests can order from the full restaurant menu without a reservation. A great strategy for busy periods.', '$12–$25/pp', 18, 'lounge_bar', 'American bar bites', 'N/A'),
  ('d-outer-rim', 'Outer Rim', 'CR', 'restaurant', 'A lounge on the fourth floor of the Contemporary with monorail views and cocktails. A classic Disney bar stop with a relaxed, mid-century feel.', '$10–$20/pp', 15, 'lounge_bar', 'Cocktails & snacks', 'N/A'),
  ('s-contempo-cafe', 'Contempo Cafe', 'CR', 'snack', 'One of the best resort quick service options. Located in the Contemporary''s Grand Canyon Concourse with sandwiches, flatbreads, and Mickey-shaped rice crispy treats. Supports mobile order.', '$12–$18/pp', 15, 'quick_service', 'American', 'QS'),
  ('s-the-sand-bar', 'The Sand Bar', 'CR', 'snack', 'Pool bar at the Contemporary''s main pool serving sandwiches, snacks, and cocktails. Resort guests only.', '$10–$18/pp', 14, 'pool_bar', 'Drinks & American snacks', 'QS'),
  ('s-cove-bar', 'Cove Bar', 'CR', 'snack', 'Pool bar at Bay Lake Tower''s pool — accessible only to Bay Lake Tower guests. Light snacks and beverages.', '$8–$15/pp', 11, 'pool_bar', 'Drinks & snacks', 'QS'),
  ('s-contemporary-grounds', 'Contemporary Grounds', 'CR', 'snack', 'A coffee kiosk in the Contemporary''s lobby area serving espresso drinks, grab-and-go pastries, and snacks. A convenient early morning stop.', '$5–$12/pp', 8, 'snack_kiosk', 'Coffee & pastries', 'QS/Snack'),
  ('d-ohana', '''Ohana', 'POLY', 'restaurant', 'Beloved family-style feast with Polynesian-inspired meats, noodles, and vegetables. Breakfast features Lilo, Stitch, Mickey, and Pluto. Dinner is all-you-care-to-enjoy. Warm, communal atmosphere.', '$50–$70/pp', 60, 'table_service', 'Hawaiian-American family-style', '1'),
  ('d-kona-cafe', 'Kona Cafe', 'POLY', 'restaurant', 'Pacific Rim-inspired restaurant in the Polynesian lobby. Famous for Tonga Toast (banana-stuffed bread, deep fried, rolled in cinnamon sugar). More relaxed and easier to book than ''Ohana.', '$30–$55/pp', 42, 'table_service', 'Pan-Asian American', '1'),
  ('d-wailulu-bar-and-grill', 'Wailulu Bar & Grill', 'POLY', 'restaurant', 'A table service restaurant at the Polynesian Island Tower (Sesame Street-themed DVC addition) serving American casual meals with Polynesian touches. Lunch and dinner.', '$30–$50/pp', 40, 'table_service', 'American tropical', '1'),
  ('d-tambu-lounge', 'Tambu Lounge', 'POLY', 'restaurant', 'The lounge adjacent to ''Ohana serving Polynesian-inspired cocktails and the full ''Ohana menu without a reservation. A great insider tip for eating at ''Ohana when it''s fully booked.', '$10–$22/pp', 16, 'lounge_bar', 'Polynesian cocktails & bites', 'N/A'),
  ('d-trader-sam-s-grog-grotto', 'Trader Sam''s Grog Grotto', 'POLY', 'restaurant', 'A beloved tiki-themed bar inside the Polynesian with theatrical cocktails that trigger sound and light effects in the room. No reservations — often has a wait. One of Disney''s most unique bar experiences.', '$12–$25/pp', 18, 'lounge_bar', 'Tiki cocktails & bar bites', 'N/A'),
  ('d-trader-sam-s-tiki-terrace', 'Trader Sam''s Tiki Terrace', 'POLY', 'restaurant', 'The outdoor overflow area for Trader Sam''s Grog Grotto with the same menu in a beautiful tiki torch setting. Great alternative when the interior is at capacity.', '$10–$20/pp', 15, 'lounge_bar', 'Tiki cocktails', 'N/A'),
  ('s-capt-cook-s', 'Capt. Cook''s', 'POLY', 'snack', 'The Polynesian''s quick service open 24 hours, with Tonga Toast at breakfast and burgers, bowls, and sandwiches for lunch and dinner. One of the best resort quick service options.', '$11–$17/pp', 14, 'quick_service', 'American & Hawaiian', 'QS'),
  ('s-pineapple-lanai', 'Pineapple Lanai', 'POLY', 'snack', 'The only resort Dole Whip stand, located in the Polynesian''s Pineapple Lanai. The Dole Whip Float (vanilla soft serve in pineapple juice) is one of Walt Disney World''s most iconic snacks.', '$5–$10/pp', 7, 'snack_kiosk', 'Dole Whip & snacks', 'QS/Snack'),
  ('s-oasis-bar-and-grill', 'Oasis Bar & Grill', 'POLY', 'snack', 'Pool bar at the Polynesian''s Lava Pool with sandwiches, cocktails, and snacks. Resort guests only.', '$10–$18/pp', 14, 'pool_bar', 'American & tropical snacks', 'QS'),
  ('s-barefoot-pool-bar', 'Barefoot Pool Bar', 'POLY', 'snack', 'A smaller pool bar at the Polynesian serving beverages and light snacks. Resort guests only.', '$8–$15/pp', 11, 'pool_bar', 'Drinks', 'N/A'),
  ('s-kona-island', 'Kona Island', 'POLY', 'snack', 'A small coffee bar in the Polynesian lobby serving espresso drinks, sushi (evenings), and pastries. A convenient stop for morning coffee before heading to the parks.', '$5–$12/pp', 8, 'snack_kiosk', 'Coffee & pastries', 'QS/Snack'),
  ('d-artist-point-with-snow-white', 'Artist Point with Snow White', 'WL', 'restaurant', 'Storybook Dining featuring Snow White, the Evil Queen, Dopey, and Grumpy in a dramatic forest setting. Dinner-only with an immersive theatrical storybook atmosphere.', '$55–$80/pp', 67, 'character_dining', 'Pacific Northwest, Snow White & villains', '2'),
  ('d-whispering-canyon-cafe', 'Whispering Canyon Cafe', 'WL', 'restaurant', 'Raucous, playful family-style restaurant where servers engage guests in games and jokes. All-you-care-to-enjoy skillets at lunch and dinner. Ask for ketchup and see what happens.', '$35–$55/pp', 45, 'table_service', 'American family-style', '1'),
  ('s-geyserpoint', 'Geyser Point Bar and Grill', 'WL', 'restaurant', 'Casual waterfront restaurant on Bay Lake with burgers, flatbreads, and seasonal cocktails. One of the most scenic casual dining spots at Walt Disney World. Walk-up friendly.', '$25–$45/pp', 35, 'table_service', 'American lakeside', '1'),
  ('d-territory-lounge', 'Territory Lounge', 'WL', 'restaurant', 'A rugged, rustic lounge inside Wilderness Lodge with creative cocktails, Pacific Northwest-inspired charcuterie boards, and small plates. No reservations — one of the best resort lounges at WDW.', '$10–$22/pp', 16, 'lounge_bar', 'Cocktails & snacks', 'N/A'),
  ('s-roaring-fork', 'Roaring Fork', 'WL', 'snack', 'The Wilderness Lodge''s quick service with burgers, sandwiches, and Mickey waffles for breakfast. Open 24 hours. A reliable and convenient option for resort guests.', '$10–$16/pp', 13, 'quick_service', 'American', 'QS'),
  ('d-yachtsman-steakhouse', 'Yachtsman Steakhouse', 'YC', 'restaurant', 'Classic American steakhouse at the Yacht Club with dry-aged prime beef, fresh seafood, and an excellent wine selection. Understated but consistently excellent.', '$85–$125/pp', 105, 'signature', 'American steakhouse', '2'),
  ('d-ale-and-compass-restaurant', 'Ale & Compass Restaurant', 'YC', 'restaurant', 'New England-inspired restaurant at the Yacht Club with lobster bisque, seafood chowder, fish and chips, and clam bakes. Solid quality with a nautical theme. Supports mobile order.', '$35–$60/pp', 47, 'table_service', 'New England seafood', '1'),
  ('d-ale-and-compass-lounge', 'Ale & Compass Lounge', 'YC', 'restaurant', 'Lounge adjacent to Ale & Compass serving the full restaurant menu without a reservation. Great alternative when the dining room is fully booked. Prime rib sliders are a standout.', '$12–$25/pp', 18, 'lounge_bar', 'Cocktails & full menu', 'N/A'),
  ('d-crew-s-cup-lounge', 'Crew''s Cup Lounge', 'YC', 'restaurant', 'A nautical-themed lounge at the Yacht Club with excellent soups, sliders, and cocktails. Walk-up friendly and one of the best lounges on property for casual dining.', '$12–$25/pp', 18, 'lounge_bar', 'Nautical bar bites & cocktails', 'N/A'),
  ('s-the-market-at-ale-and-compass', 'The Market at Ale & Compass', 'YC', 'snack', 'The Yacht Club''s quick service with grab-and-go sandwiches, salads, pastries, and coffee. Convenient for early park mornings.', '$8–$16/pp', 12, 'quick_service', 'American grab-and-go', 'QS'),
  ('d-cape-may-cafe', 'Cape May Cafe', 'BC', 'restaurant', 'New England clam bake-inspired buffet with Minnie, Donald, Daisy, and Goofy in beach attire. The only character beach party breakfast at WDW. Seafood buffet at dinner.', '$45–$65/pp', 55, 'character_dining', 'American buffet, Minnie''s Beach party', '1'),
  ('d-beaches-and-cream-soda-shop', 'Beaches & Cream Soda Shop', 'BC', 'restaurant', 'Retro soda fountain and diner famous for the Kitchen Sink — a massive sundae with every topping available. Burgers and shakes round out the menu. Reservations highly recommended.', '$20–$40/pp', 30, 'table_service', 'Ice cream & American diner', '1'),
  ('d-martha-s-vineyard-lounge', 'Martha''s Vineyard Lounge', 'BC', 'restaurant', 'A wine-focused lounge at the Beach Club with a solid wine-by-the-glass program, cocktails, and a small food menu. A quiet retreat within the resort.', '$10–$20/pp', 15, 'lounge_bar', 'Wine & cocktails', 'N/A'),
  ('s-beach-club-marketplace', 'Beach Club Marketplace', 'BC', 'snack', 'The Beach Club''s quick service with grab-and-go items, baked goods, and coffee. Better for snacks and breakfast than full meals.', '$6–$15/pp', 10, 'quick_service', 'Grab-and-go & snacks', 'QS'),
  ('s-hurricane-hanna-s-waterside', 'Hurricane Hanna''s Waterside Bar and Grill', 'BC', 'snack', 'Pool bar between the Beach and Yacht Clubs at Stormalong Bay serving burgers, sandwiches, loaded fries, and cocktails. Open to guests of both resorts. Famous for the loaded crab fries.', '$11–$18/pp', 14, 'pool_bar', 'American burgers & snacks', 'QS'),
  ('d-flying-fish', 'Flying Fish', 'BW', 'restaurant', 'Elegant beachside-themed seafood restaurant on the BoardWalk with creative fresh fish preparations and prime beef. One of the most respected signature restaurants at WDW for consistent food quality.', '$80–$120/pp', 100, 'signature', 'Seafood & steakhouse', '2'),
  ('d-trattoria-al-forno', 'Trattoria al Forno', 'BW', 'restaurant', 'Rustic Italian restaurant on the BoardWalk with house-made pastas and wood-fired dishes. Character breakfast available with Rapunzel, Flynn Rider, Ariel, and Prince Eric.', '$35–$60/pp', 47, 'table_service', 'Italian', '1'),
  ('d-the-cake-bake-shop-by', 'The Cake Bake Shop by Gwendolyn Rogers', 'BW', 'restaurant', 'A charming Indianapolis bakery concept brought to the BoardWalk. Serves brunch and dinner with elaborate layer cakes, pastries, and whimsical decor. Not on the dining plan. A newer and popular addition.', '$30–$55/pp', 42, 'table_service', 'American bakery & brunch', 'N/A'),
  ('d-abracadabar', 'AbracadaBar', 'BW', 'restaurant', 'A magician-themed bar on the BoardWalk with interactive magic tricks built into the decor and cocktail menu. A fan-favorite Disney bar concept.', '$10–$22/pp', 16, 'lounge_bar', 'Cocktails & bar bites', 'N/A'),
  ('d-belle-vue-lounge', 'Belle Vue Lounge', 'BW', 'restaurant', 'A quiet lounge at the BoardWalk Inn serving cocktails in the evening and continental breakfast items in the morning. A peaceful alternative to the busier BoardWalk.', '$8–$20/pp', 14, 'lounge_bar', 'Cocktails & continental breakfast', 'N/A'),
  ('s-boardwalk-deli', 'BoardWalk Deli', 'BW', 'snack', 'A classic New York-style deli on the BoardWalk with subs, sandwiches, pastries, and coffee. A reliable grab-and-go breakfast or lunch stop.', '$10–$16/pp', 13, 'quick_service', 'Deli sandwiches', 'QS'),
  ('s-carousel-coffee', 'Carousel Coffee', 'BW', 'snack', 'A coffee and pastry kiosk on the BoardWalk. Convenient morning stop with espresso drinks, baked goods, and grab-and-go snacks.', '$5–$12/pp', 8, 'quick_service', 'Coffee & pastries', 'QS'),
  ('s-pizza-window', 'Pizza Window', 'BW', 'snack', 'A late-night pizza window on the BoardWalk serving whole pies and slices. One of the more popular late-night food options on the Epcot resort area.', '$8–$14/pp', 11, 'quick_service', 'Pizza', 'QS'),
  ('s-leaping-horse-libations', 'Leaping Horse Libations', 'BW', 'snack', 'Pool bar at the BoardWalk''s Luna Park Pool serving cocktails, beer, and light snacks. Resort guests only.', '$8–$15/pp', 11, 'pool_bar', 'Drinks & snacks', 'QS'),
  ('s-boardwalk-joe-s-marvelous', 'Boardwalk Joe''s Marvelous Margaritas', 'BW', 'snack', 'An outdoor kiosk on the BoardWalk promenade famous for frozen margaritas. A classic BoardWalk stop for an evening stroll drink.', '$8–$14/pp', 11, 'snack_kiosk', 'Margaritas & snacks', 'N/A'),
  ('d-jiko-the-cooking-place', 'Jiko – The Cooking Place', 'AKL', 'restaurant', 'African-inspired fine dining at Animal Kingdom Lodge with flavors from across the continent and a celebrated African wine program. One of Walt Disney World''s most distinctive signature restaurants.', '$80–$120/pp', 100, 'signature', 'African-inspired fine dining', '2'),
  ('d-boma-flavors-of-africa', 'Boma – Flavors of Africa', 'AKL', 'restaurant', 'An extensive African-inspired buffet with dishes from across the continent — soups, stews, roasted meats, and unique desserts. One of the best resort buffets at Walt Disney World.', '$40–$60/pp', 50, 'table_service', 'African buffet', '1'),
  ('d-sanaa', 'Sanaa', 'AKL', 'restaurant', 'Located at Kidani Village with savanna views, Sanaa serves Indian-spiced African dishes including the famous bread service with multiple sauces. A hidden gem — easier to book than the lodge restaurants.', '$35–$55/pp', 45, 'table_service', 'Indian-African fusion', '1'),
  ('d-victoria-falls-lounge', 'Victoria Falls Lounge', 'AKL', 'restaurant', 'A lounge above Boma with views of the savanna and a menu of African-inspired cocktails and small plates. A beautiful, relaxing resort bar.', '$10–$22/pp', 16, 'lounge_bar', 'Cocktails & small plates', 'N/A'),
  ('d-cape-town-lounge-and-wine-bar', 'Cape Town Lounge and Wine Bar', 'AKL', 'restaurant', 'A dedicated wine bar adjacent to Jiko focusing on African wines — the largest selection of African wines in North America. Excellent small plates. Walk-up, no reservations.', '$12–$28/pp', 20, 'lounge_bar', 'African wines & small plates', 'N/A'),
  ('s-the-mara', 'The Mara', 'AKL', 'snack', 'The main quick service at Animal Kingdom Lodge. African-inspired breakfast items and American standards for lunch and dinner. A solid and convenient resort option.', '$11–$17/pp', 14, 'quick_service', 'African-American', 'QS'),
  ('s-maji-pool-bar', 'Maji Pool Bar', 'AKL', 'snack', 'Pool bar at the Jambo House main pool with cocktails, beer, and snacks. Savanna views from the pool area make this a scenic stop.', '$8–$15/pp', 11, 'pool_bar', 'Drinks & snacks', 'QS'),
  ('s-uzima-springs-pool-bar', 'Uzima Springs Pool Bar', 'AKL', 'snack', 'Pool bar at the Kidani Village pool area serving beverages and light snacks. Resort guests only.', '$8–$15/pp', 11, 'pool_bar', 'Drinks & snacks', 'QS'),
  ('d-sanaa-lounge', 'Sanaa Lounge', 'AKL', 'restaurant', 'Walk-up lounge adjacent to Sanaa at Kidani Village serving cocktails and small plates with savanna views. Great alternative when Sanaa is fully booked.', '$10–$22/pp', 16, 'lounge_bar', 'Indian-African small plates & cocktails', 'N/A'),
  ('d-shula-s-steak-house', 'Shula''s Steak House', 'SWD', 'restaurant', 'An upscale steakhouse at the Dolphin hotel with USDA prime beef, fresh seafood, and an extensive wine list. Not on the Disney Dining Plan but a respected fine dining option in the Epcot resort area.', '$90–$140/pp', 115, 'signature', 'American steakhouse', 'N/A'),
  ('d-todd-english-s-bluezoo', 'Todd English''s bluezoo', 'SWD', 'restaurant', 'Celebrity chef Todd English''s coastal seafood restaurant at the Dolphin. Creative preparations of fresh fish and seafood in a sophisticated, underwater-inspired setting.', '$80–$120/pp', 100, 'signature', 'Coastal seafood', 'N/A'),
  ('d-il-mulino-new-york-trattoria', 'Il Mulino New York Trattoria', 'SWD', 'restaurant', 'A New York-style Italian restaurant at the Swan with classic pastas, veal, and seafood. Not on the Disney Dining Plan.', '$40–$70/pp', 55, 'table_service', 'Italian', 'N/A'),
  ('d-rosa-mexicano', 'Rosa Mexicano', 'SWD', 'restaurant', 'Upscale Mexican restaurant at the Dolphin known for tableside guacamole and regional Mexican dishes. Not on the Disney Dining Plan.', '$35–$60/pp', 47, 'table_service', 'Mexican', 'N/A'),
  ('d-garden-grove', 'Garden Grove', 'SWD', 'restaurant', 'A garden-themed restaurant at the Swan with buffet breakfast (including character dining on select days) and à la carte dinner. Not on the Disney Dining Plan.', '$35–$60/pp', 47, 'table_service', 'American buffet & character dining', 'N/A'),
  ('d-kimonos', 'Kimonos', 'SWD', 'restaurant', 'A Japanese sushi bar and karaoke lounge at the Swan. Excellent sushi at competitive prices, plus karaoke entertainment nightly. A fun, adult-oriented option. Not on the dining plan.', '$15–$35/pp', 25, 'lounge_bar', 'Japanese sushi & karaoke', 'N/A'),
  ('s-cabana-bar-and-beach-club', 'Cabana Bar and Beach Club', 'SWD', 'snack', 'Pool bar at the Swan & Dolphin''s main pool area. Burgers, sandwiches, and cocktails in a waterfront setting.', '$10–$18/pp', 14, 'pool_bar', 'American snacks & drinks', 'N/A'),
  ('s-the-fountain', 'The Fountain', 'SWD', 'snack', 'A casual diner-style counter service at the Dolphin with burgers, hot dogs, and ice cream. Not on the Disney Dining Plan.', '$10–$16/pp', 13, 'quick_service', 'American burgers & shakes', 'N/A'),
  ('d-topolinos', 'Topolino''s Terrace', 'RIV', 'restaurant', 'Rooftop restaurant inspired by the French and Italian Riviera. Character breakfast (Minnie, Mickey, Donald, Daisy in artist attire) uses 1 credit; dinner is Signature using 2 credits. Excellent food with lovely resort views.', '$75–$110/pp', 92, 'signature', 'French-Italian rooftop', '2 (D) / 1 (B)'),
  ('d-bar-riva', 'Bar Riva', 'RIV', 'restaurant', 'A stylish pool-adjacent bar at the Riviera serving Mediterranean-inspired cocktails and quality small plates. Walk-up, no reservations. One of the best resort bars for food quality.', '$12–$25/pp', 18, 'lounge_bar', 'Mediterranean cocktails & small plates', 'N/A'),
  ('s-primo-piatto', 'Primo Piatto', 'RIV', 'snack', 'Widely regarded as the best quick service at any Disney resort. Upscale counter service with quality sandwiches, pasta bowls, flatbreads, and pastries. Supports mobile order.', '$12–$18/pp', 15, 'quick_service', 'Italian-American', 'QS'),
  ('s-le-petit-cafe', 'Le Petit Cafe', 'RIV', 'snack', 'A small café kiosk at the Riviera lobby serving French pastries, espresso drinks, and light snacks. A charming morning stop for resort guests.', '$5–$12/pp', 8, 'snack_kiosk', 'French pastries & coffee', 'QS/Snack'),
  ('d-toledo-tapas-steak-and-seafood', 'Toledo – Tapas, Steak & Seafood', 'CSR', 'restaurant', 'Rooftop restaurant atop Gran Destino Tower with panoramic resort views. Spanish-inspired tapas, paella, and premium steaks. A lesser-known Signature that''s easier to book than other fine dining options.', '$70–$110/pp', 90, 'signature', 'Spanish rooftop', '2'),
  ('d-three-bridges-bar-and-grill', 'Three Bridges Bar & Grill at Villa del Lago', 'CSR', 'restaurant', 'Open-air restaurant on a small island in the resort''s lake, accessible by three bridges. Burgers, flatbreads, and Latin-inspired snacks. One of Disney''s most scenic casual dining spots.', '$25–$45/pp', 35, 'table_service', 'American lakeside', '1'),
  ('d-maya-grill', 'Maya Grill', 'CSR', 'restaurant', 'Latin American restaurant at Coronado Springs with Mesoamerican-inspired dishes — grilled meats, tamales, and seafood. Dinner only.', '$35–$55/pp', 45, 'table_service', 'Latin American', '1'),
  ('d-rix-sports-bar-and-grill', 'Rix Sports Bar and Grill', 'CSR', 'restaurant', 'A sports bar and grill with American comfort food — burgers, wings, nachos — and multiple screens showing live sports. A lively casual dining option at the resort.', '$20–$40/pp', 30, 'table_service', 'American sports bar', '1'),
  ('d-barcelona-lounge', 'Barcelona Lounge', 'CSR', 'restaurant', 'A lounge in Gran Destino Tower with Spanish-inspired cocktails and small plates. Serves breakfast, making it one of the few resort lounges open in the morning.', '$10–$22/pp', 16, 'lounge_bar', 'Spanish-inspired cocktails & tapas', 'N/A'),
  ('d-dahlia-lounge', 'Dahlia Lounge', 'CSR', 'restaurant', 'A lounge near the convention center at Coronado Springs with cocktails and bar snacks including notably good chicken wings.', '$10–$20/pp', 15, 'lounge_bar', 'Cocktails & bar snacks', 'N/A'),
  ('s-cafe-rix', 'Cafe Rix', 'CSR', 'snack', 'The main quick service at Gran Destino Tower with sandwiches, flatbreads, and pastries. A step above the main resort food court.', '$10–$17/pp', 13, 'quick_service', 'International', 'QS'),
  ('s-el-mercado-de-coronado', 'El Mercado de Coronado', 'CSR', 'snack', 'The main food court at Coronado Springs with multiple stations serving Mexican-inspired dishes, American classics, and breakfast items.', '$10–$17/pp', 13, 'quick_service', 'Mexican-American food court', 'QS'),
  ('s-siestas-cantina', 'Siestas Cantina', 'CSR', 'snack', 'Pool bar at Coronado Springs'' Dig Site pool area with Mexican-inspired snacks, margaritas, and cocktails. Resort guests only.', '$8–$15/pp', 11, 'pool_bar', 'Drinks & Mexican snacks', 'QS'),
  ('s-laguna-pool-bar', 'Laguna Pool Bar', 'CSR', 'snack', 'A smaller pool bar at Coronado Springs with beverages. Resort guests only.', '$8–$14/pp', 11, 'pool_bar', 'Drinks', 'N/A'),
  ('d-sebastian-s-bistro', 'Sebastian''s Bistro', 'CBR', 'restaurant', 'Caribbean-inspired restaurant at Caribbean Beach Resort inspired by The Little Mermaid''s Sebastian. Creative fusion dishes with tropical flavors — one of the more interesting moderate resort table service options.', '$35–$55/pp', 45, 'table_service', 'Caribbean fusion', '1'),
  ('s-centertown-market', 'Centertown Market', 'CBR', 'snack', 'The main food court at Caribbean Beach with Caribbean-inspired dishes, American staples, and a solid rotating menu. One of the more improved moderate resort quick service options in recent years.', '$11–$17/pp', 14, 'quick_service', 'Caribbean-American food court', 'QS'),
  ('s-spyglass-grill', 'Spyglass Grill', 'CBR', 'snack', 'Pool bar at Caribbean Beach''s Fuentes del Morro pool serving burgers, sandwiches, cocktails, and snacks. Resort guests only.', '$10–$18/pp', 14, 'pool_bar', 'American burgers & drinks', 'QS'),
  ('s-banana-cabana', 'Banana Cabana', 'CBR', 'snack', 'A pool bar at Caribbean Beach serving tropical cocktails, beer, and light snacks at the Fuentes del Morro pool. Resort guests only.', '$8–$15/pp', 11, 'pool_bar', 'Tropical drinks & snacks', 'QS'),
  ('d-boatwright-s-dining-hall', 'Boatwright''s Dining Hall', 'PORS', 'restaurant', 'Rustic boat-building themed restaurant at Port Orleans Riverside with Cajun-inspired comfort food — jambalaya, gumbo, catfish, and hearty Southern sides. A great value resort table service.', '$30–$50/pp', 40, 'table_service', 'Cajun-Southern American', '1'),
  ('s-riverside-mill-food-court', 'Riverside Mill Food Court', 'PORS', 'snack', 'Port Orleans Riverside''s main food court with multiple stations and a good selection including shrimp and grits, pasta, burgers, and breakfast items.', '$10–$16/pp', 13, 'quick_service', 'American food court', 'QS'),
  ('d-river-roost', 'River Roost', 'PORS', 'restaurant', 'A rustic lounge at Port Orleans Riverside with a casual bar atmosphere. Live entertainment on select evenings. A relaxed option for resort guests.', '$8–$18/pp', 13, 'lounge_bar', 'Southern cocktails & bar bites', 'N/A'),
  ('s-muddy-rivers', 'Muddy Rivers', 'PORS', 'snack', 'Pool bar at the Ol'' Man Island pool at Port Orleans Riverside. Cocktails, beer, and light snacks. Resort guests only.', '$8–$14/pp', 11, 'pool_bar', 'Drinks & snacks', 'QS'),
  ('s-sassagoula-floatworks-and', 'Sassagoula Floatworks and Food Factory', 'POFQ', 'snack', 'Port Orleans French Quarter''s food court with Cajun-inspired dishes and American classics. Famous for Mickey-shaped beignets — a must-have for resort guests.', '$10–$16/pp', 13, 'quick_service', 'American & Cajun food court', 'QS'),
  ('s-scat-cat-s-club-cafe', 'Scat Cat''s Club Cafe', 'POFQ', 'snack', 'A casual lounge-style counter service at Port Orleans French Quarter with cocktails, beer, and lighter snack options.', '$6–$12/pp', 9, 'quick_service', 'Snacks & light bites', 'QS'),
  ('s-mardi-grogs', 'Mardi Grogs', 'POFQ', 'snack', 'Pool bar at the Doubloon Lagoon pool at Port Orleans French Quarter. Mardi Gras-themed cocktails and light snacks. Resort guests only.', '$8–$14/pp', 11, 'pool_bar', 'Drinks & snacks', 'QS'),
  ('d-hoop-dee-doo-musical-revue', 'Hoop-Dee-Doo Musical Revue', 'FW', 'restaurant', 'Disney''s longest-running dinner show — all-you-care-to-enjoy Western BBQ (fried chicken, ribs, corn, beans, strawberry shortcake) with live country-comedy stage show. A genuine institution. Book at the 60-day window.', '$75–$85/pp', 80, 'dinner_show', 'American BBQ, Western comedy show', '2'),
  ('d-trail-s-end-restaurant', 'Trail''s End Restaurant', 'FW', 'restaurant', 'Relaxed, rustic restaurant at Fort Wilderness with generous American classics — fried chicken, BBQ, and comfort sides. One of the best value table service meals on Disney property.', '$25–$45/pp', 35, 'table_service', 'American', '1'),
  ('d-crockett-s-tavern', 'Crockett''s Tavern', 'FW', 'restaurant', 'A frontier-themed bar at Fort Wilderness with cocktails, beer, and bar snacks. A laid-back stop for campground guests.', '$8–$18/pp', 13, 'lounge_bar', 'American bar snacks & cocktails', 'N/A'),
  ('s-the-chuck-wagon', 'The Chuck Wagon', 'FW', 'snack', 'Outdoor counter service at the campground serving BBQ, burgers, and American staples. A casual, no-frills option for Fort Wilderness campers.', '$10–$16/pp', 13, 'quick_service', 'BBQ & American', 'QS'),
  ('s-meadow-take-out', 'Meadow Take Out', 'FW', 'snack', 'A small quick service kiosk at the Meadow area of Fort Wilderness serving pizza, sandwiches, and snacks.', '$8–$14/pp', 11, 'quick_service', 'American snacks & pizza', 'QS'),
  ('s-p-and-j-s-southern-takeout', 'P & J''s Southern Takeout', 'FW', 'snack', 'A small counter service spot at Fort Wilderness serving Southern-inspired items including chicken, sides, and drinks.', '$8–$14/pp', 11, 'quick_service', 'Southern American', 'QS'),
  ('d-the-turf-club-bar-and-grill', 'The Turf Club Bar and Grill', 'SS', 'restaurant', 'Horse racing-themed restaurant at Saratoga Springs with American classics — burgers, salads, and seasonal specials. A quiet, relaxed option for resort guests near Disney Springs.', '$30–$50/pp', 40, 'table_service', 'American', '1'),
  ('d-the-turf-club-lounge', 'The Turf Club Lounge', 'SS', 'restaurant', 'Lounge adjacent to the Turf Club Bar and Grill with cocktails and bar snacks. Walk-up friendly.', '$10–$20/pp', 15, 'lounge_bar', 'Cocktails & bar bites', 'N/A'),
  ('s-the-artist-s-palette', 'The Artist''s Palette', 'SS', 'snack', 'One of the best resort quick service options, with a rotating menu including roasted half chicken with vegetables, sandwiches, pizza, and fresh salads.', '$11–$17/pp', 14, 'quick_service', 'American & Italian', 'QS'),
  ('s-the-paddock-grill', 'The Paddock Grill', 'SS', 'snack', 'Pool bar at Saratoga Springs serving burgers, sandwiches, and cocktails at the High Rock Spring pool area.', '$8–$15/pp', 11, 'pool_bar', 'American drinks & snacks', 'QS'),
  ('s-on-the-rocks', 'On the Rocks', 'SS', 'snack', 'A smaller pool bar at Saratoga Springs serving beverages and light snacks. Resort guests only.', '$8–$14/pp', 11, 'pool_bar', 'Drinks', 'N/A'),
  ('s-backstretch-pool-bar', 'Backstretch Pool Bar', 'SS', 'snack', 'Pool bar at Saratoga Springs'' Congress Park pool area with drinks and light snacks. Resort guests only.', '$8–$14/pp', 11, 'pool_bar', 'Drinks & snacks', 'QS'),
  ('d-olivia-s-cafe', 'Olivia''s Cafe', 'OKW', 'restaurant', 'A laid-back Keys-inspired restaurant at Old Key West serving conch fritters, lobster pizza, and Key lime pie. A lesser-known gem — excellent food, relaxed atmosphere, and almost always bookable.', '$30–$50/pp', 40, 'table_service', 'Florida Keys American', '1'),
  ('s-good-s-food-to-go', 'Good''s Food To Go', 'OKW', 'snack', 'The Old Key West quick service with grab-and-go sandwiches, salads, and light items. Convenient for resort guests near Disney Springs.', '$8–$14/pp', 11, 'quick_service', 'American grab-and-go', 'QS'),
  ('d-gurgling-suitcase-libations', 'Gurgling Suitcase Libations and Spirits', 'OKW', 'restaurant', 'A small, charming bar at Old Key West with tropical cocktails and light snacks. A beloved low-key spot for DVC members and resort fans.', '$8–$18/pp', 13, 'lounge_bar', 'Tropical cocktails & snacks', 'N/A'),
  ('s-turtle-shack-poolside-snacks', 'Turtle Shack Poolside Snacks', 'OKW', 'snack', 'Pool bar at Old Key West''s main pool with light snacks and beverages. Resort guests only.', '$8–$14/pp', 11, 'pool_bar', 'Drinks & snacks', 'QS'),
  ('s-world-premiere-food-court-all', 'World Premiere Food Court (All-Star Movies)', 'VALUE', 'snack', 'All-Star Movies Resort food court with multiple stations serving breakfast classics, burgers, pasta, and pizza. Standard value resort food court with broad options.', '$9–$15/pp', 12, 'quick_service', 'American food court', 'QS'),
  ('s-intermission-food-court-all', 'Intermission Food Court (All-Star Music)', 'VALUE', 'snack', 'All-Star Music Resort food court with multiple stations. Breakfast, burgers, pizza, and rotating entrées. Standard value resort dining.', '$9–$15/pp', 12, 'quick_service', 'American food court', 'QS'),
  ('s-end-zone-food-court-all-star', 'End Zone Food Court (All-Star Sports)', 'VALUE', 'snack', 'All-Star Sports Resort food court with a sports bar aesthetic and typical value resort menu — burgers, pasta, pizza, and breakfast items.', '$9–$15/pp', 12, 'quick_service', 'American food court', 'QS'),
  ('s-everything-pop-dining-pop', 'Everything POP Dining (Pop Century)', 'VALUE', 'snack', 'Pop Century Resort''s food court with a fun pop culture theme. Standard offerings — pizza, burgers, and breakfast — with Pop Century''s signature colorful decor.', '$9–$15/pp', 12, 'quick_service', 'American food court', 'QS'),
  ('s-landscape-of-flavors-art-of', 'Landscape of Flavors (Art of Animation)', 'VALUE', 'snack', 'Art of Animation Resort''s food court with theming from Finding Nemo, Cars, The Lion King, and The Little Mermaid. Standard quick service offerings in a colorful, fun setting.', '$9–$15/pp', 12, 'quick_service', 'American food court', 'QS'),
  ('s-silver-screen-spirits-all', 'Silver Screen Spirits (All-Star Movies)', 'VALUE', 'snack', 'Pool bar at All-Star Movies serving beverages and light snacks. Resort guests only.', '$8–$14/pp', 11, 'pool_bar', 'Drinks', 'N/A'),
  ('s-singing-spirits-all-star-music', 'Singing Spirits (All-Star Music)', 'VALUE', 'snack', 'Pool bar at All-Star Music serving beverages and light snacks. Resort guests only.', '$8–$14/pp', 11, 'pool_bar', 'Drinks', 'N/A'),
  ('s-grandstand-spirits-all-star', 'Grandstand Spirits (All-Star Sports)', 'VALUE', 'snack', 'Pool bar at All-Star Sports serving beverages and light snacks. Resort guests only.', '$8–$14/pp', 11, 'pool_bar', 'Drinks', 'N/A'),
  ('s-petals-pool-bar-pop-century', 'Petals Pool Bar (Pop Century)', 'VALUE', 'snack', 'Pool bar at Pop Century''s Hippy Dippy Pool with cocktails, beer, and light snacks. Resort guests only.', '$8–$14/pp', 11, 'pool_bar', 'Drinks & snacks', 'QS'),
  ('s-the-drop-off-pool-bar-art-of', 'The Drop-Off Pool Bar (Art of Animation)', 'VALUE', 'snack', 'Pool bar at Art of Animation''s Big Blue Pool with beverages and snacks. Resort guests only.', '$8–$14/pp', 11, 'pool_bar', 'Drinks & snacks', 'QS')
